fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    
    // Append all elements from v1
    for &item in v1 {
        result.push(item);
    }
    
    // Append all elements from v2
    for &item in v2 {
        result.push(item);
    }
    
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // First, take all elements of A except the last one
    let first_part = &first[0..first.len() - 1];
    
    // Then append all elements of B
    let mut result = Vec::with_capacity(first_part.len() + second.len());
    
    // Copy elements from first_part (A without last element)
    for &item in first_part {
        result.push(item);
    }
    
    // Copy all elements from second (B)
    for &item in second {
        result.push(item);
    }
    
    result
}